changeSet.sql:
ALTER TABLE siamois_document ADD COLUMN IF NOT EXISTS identifier varchar(255), ADD COLUMN IF NOT EXISTS generated_number integer, ADD COLUMN IF NOT EXISTS other_identifiers varchar(1024), ADD COLUMN IF NOT EXISTS fk_action_unit_id bigint, ADD COLUMN IF NOT EXISTS fk_category bigint, ADD COLUMN IF NOT EXISTS fk_document_type bigint, ADD COLUMN IF NOT EXISTS fk_language bigint, ADD COLUMN IF NOT EXISTS production_date timestamp with time zone, ADD COLUMN IF NOT EXISTS publisher varchar(255), ADD COLUMN IF NOT EXISTS rights varchar(5000), ADD COLUMN IF NOT EXISTS comments varchar(5000), ADD COLUMN IF NOT EXISTS format_text varchar(255), ADD COLUMN IF NOT EXISTS item_count integer, ADD COLUMN IF NOT EXISTS size_mb numeric(14, 3), ADD COLUMN IF NOT EXISTS crs varchar(255), ADD COLUMN IF NOT EXISTS original_path varchar(5000), ADD COLUMN IF NOT EXISTS external_url varchar(2048);
ALTER TABLE siamois_document ALTER COLUMN title TYPE varchar(1024); ALTER TABLE siamois_document ALTER COLUMN doc_description TYPE varchar(5000);
DO $$ BEGIN IF to_regclass('siamois_document_aud') IS NOT NULL THEN ALTER TABLE siamois_document_aud ALTER COLUMN title TYPE varchar(1024); ALTER TABLE siamois_document_aud ALTER COLUMN doc_description TYPE varchar(5000); END IF; END $$;

DO $$ DECLARE orphans integer; orphan_ids text; BEGIN -- 1. the project the document was linked to IF to_regclass('action_unit_document') IS NOT NULL THEN UPDATE siamois_document d SET fk_action_unit_id = l.fk_action_unit_id FROM (SELECT fk_document_id, min(fk_action_unit_id) AS fk_action_unit_id FROM action_unit_document GROUP BY fk_document_id) l WHERE d.document_id = l.fk_document_id AND d.fk_action_unit_id IS NULL; END IF;
-- 2. the project of a linked recording unit IF to_regclass('recording_unit_document') IS NOT NULL THEN UPDATE siamois_document d SET fk_action_unit_id = l.fk_action_unit_id FROM (SELECT rud.fk_document_id, min(ru.fk_action_unit_id) AS fk_action_unit_id FROM recording_unit_document rud JOIN recording_unit ru ON ru.recording_unit_id = rud.fk_recording_unit_id WHERE ru.fk_action_unit_id IS NOT NULL GROUP BY rud.fk_document_id) l WHERE d.document_id = l.fk_document_id AND d.fk_action_unit_id IS NULL; END IF;
-- 3. the project of the recording unit of a linked find IF to_regclass('specimen_document') IS NOT NULL THEN UPDATE siamois_document d SET fk_action_unit_id = l.fk_action_unit_id FROM (SELECT sd.fk_document_id, min(coalesce(s.fk_action_unit_id, ru.fk_action_unit_id)) AS fk_action_unit_id FROM specimen_document sd JOIN specimen s ON s.specimen_id = sd.fk_specimen_id LEFT JOIN recording_unit ru ON ru.recording_unit_id = s.fk_recording_unit_id WHERE coalesce(s.fk_action_unit_id, ru.fk_action_unit_id) IS NOT NULL GROUP BY sd.fk_document_id) l WHERE d.document_id = l.fk_document_id AND d.fk_action_unit_id IS NULL; END IF;
-- 4. the only project whose spatial context holds a linked place IF to_regclass('spatial_unit_document') IS NOT NULL THEN UPDATE siamois_document d SET fk_action_unit_id = l.fk_action_unit_id FROM (SELECT p.fk_document_id, min(p.fk_action_unit_id) AS fk_action_unit_id FROM (SELECT DISTINCT sud.fk_document_id, ausc.fk_action_unit_id FROM spatial_unit_document sud JOIN action_unit_spatial_context ausc ON ausc.fk_spatial_unit_id = sud.fk_spatial_unit_id) p GROUP BY p.fk_document_id HAVING count(*) = 1) l WHERE d.document_id = l.fk_document_id AND d.fk_action_unit_id IS NULL; END IF;
SELECT count(*), string_agg(document_id::text, ', ' ORDER BY document_id) INTO orphans, orphan_ids FROM siamois_document WHERE fk_action_unit_id IS NULL; IF orphans > 0 THEN RAISE NOTICE 'Documents migration: % document(s) could not be attached to a project and need a manual repair (document_id: %)', orphans, orphan_ids; END IF; END $$;

UPDATE siamois_document SET identifier = 'DOC-' || document_id WHERE identifier IS NULL;
ALTER TABLE siamois_document ALTER COLUMN identifier SET NOT NULL;
-- unique per project; documents still without a project do not collide (NULLs are distinct)
CREATE UNIQUE INDEX IF NOT EXISTS uk_document_project_identifier
    ON siamois_document (fk_action_unit_id, identifier);

CREATE TABLE IF NOT EXISTS document_support_nature (
    fk_document_id bigint NOT NULL,
    fk_concept_id bigint NOT NULL,
    PRIMARY KEY (fk_document_id, fk_concept_id)
);

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'siamois_document' AND column_name = 'fk_nature') THEN
        INSERT INTO document_support_nature (fk_document_id, fk_concept_id)
        SELECT document_id, fk_nature FROM siamois_document WHERE fk_nature IS NOT NULL
        ON CONFLICT DO NOTHING;
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'siamois_document' AND column_name = 'fk_format') THEN
        UPDATE siamois_document d
        SET format_text = (SELECT cl.label::text
                           FROM concept_label cl
                           WHERE cl.fk_concept_id = d.fk_format AND cl.label_type = 0
                           ORDER BY cl.concept_label_id LIMIT 1)
        WHERE d.fk_format IS NOT NULL AND d.format_text IS NULL;
    END IF;
END $$;
